input.command:
env | grep -i claude | sed 's/=.*/=<set>/' ; echo "--- python:"; which python3 && python3 --version; echo "--- node:"; which node && node --version; echo "--- jq:"; which jq; echo "--- transcript sample types:"; f=~/.claude/projects/-Users-matteodospina-orca-vela/1adaf043-50f4-43fa-825d-2c09407d0f42.jsonl; python3 -c "
import json,sys,collections
c=collections.Counter()
for l in open('$f'):
    try: d=json.loads(l)
    except: continue
    t=d.get('type'); 
    if t in('user','assistant'):
        m=d.get('message',{}); cont=m.get('content')
        if isinstance(cont,list):
            for b in cont: c[(t,b.get('type'))]+=1
        else: c[(t,'str')]+=1
    else: c[(t,)]+=1
print(c)
